// Times the trained LightGBM model compiled to C++ (generated by scripts/benchmark_trained_model.py)
// on real feature rows, and checks its raw scores against LightGBM's own predictions.
//
// Usage: trained_model_benchmark <features.bin> <lightgbm_raw_scores.bin> <n_rows>
// Prints a human-readable summary, then one JSON line with the results.

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

#include "btc_lightgbm_model.hpp"

using Clock = std::chrono::steady_clock;

template <typename T>
static std::vector<T> read_bin(const std::string& path, std::size_t count) {
    std::vector<T> v(count);
    std::ifstream f(path, std::ios::binary);
    if (!f.read(reinterpret_cast<char*>(v.data()), static_cast<std::streamsize>(count * sizeof(T)))) {
        std::cerr << "failed to read " << path << "\n";
        std::exit(1);
    }
    return v;
}

static int argmax(const double* s) {
    return static_cast<int>(std::max_element(s, s + btc_model::kNumClass) - s);
}

int main(int argc, char** argv) {
    if (argc < 4) {
        std::cerr << "usage: trained_model_benchmark <features.bin> <raw_scores.bin> <n_rows>\n";
        return 1;
    }
    const std::size_t n = std::stoul(argv[3]);
    const int nf = btc_model::kNumFeatures, nc = btc_model::kNumClass;
    auto x = read_bin<float>(argv[1], n * nf);
    auto ref = read_bin<double>(argv[2], n * nc);

    // Correctness: raw scores and predicted class vs LightGBM
    std::vector<double> out(nc);
    double max_diff = 0.0;
    std::size_t agree = 0;
    for (std::size_t i = 0; i < n; ++i) {
        btc_model::predict_raw(&x[i * nf], out.data());
        for (int c = 0; c < nc; ++c) max_diff = std::max(max_diff, std::abs(out[c] - ref[i * nc + c]));
        agree += argmax(out.data()) == argmax(&ref[i * nc]);
    }

    // Warm-up, then time one prediction at a time (the latency a live system sees per update)
    double sink = 0.0;
    for (std::size_t i = 0; i < std::min<std::size_t>(n, 2000); ++i) {
        btc_model::predict_raw(&x[i * nf], out.data());
        sink += out[0];
    }
    std::vector<double> ns(n);
    for (std::size_t i = 0; i < n; ++i) {
        auto t0 = Clock::now();
        btc_model::predict_raw(&x[i * nf], out.data());
        auto t1 = Clock::now();
        sink += out[0];
        ns[i] = std::chrono::duration<double, std::nano>(t1 - t0).count();
    }
    // Batch throughput: amortizes the clock-read overhead included in the per-call numbers
    auto b0 = Clock::now();
    for (std::size_t i = 0; i < n; ++i) {
        btc_model::predict_raw(&x[i * nf], out.data());
        sink += out[0];
    }
    auto b1 = Clock::now();
    const double batch_ns = std::chrono::duration<double, std::nano>(b1 - b0).count() / static_cast<double>(n);

    std::sort(ns.begin(), ns.end());
    auto pct = [&](double p) { return ns[static_cast<std::size_t>(p * (n - 1))]; };
    std::printf("rows %zu | max |diff| vs LightGBM %.3g | class agreement %.4f\n", n, max_diff,
                static_cast<double>(agree) / n);
    std::printf("single-row latency: p50 %.0f ns | p99 %.0f ns | p99.9 %.0f ns | batch %.0f ns/row (sink %.3f)\n",
                pct(0.50), pct(0.99), pct(0.999), batch_ns, sink);
    std::printf("{\"p50_ns\": %.1f, \"p99_ns\": %.1f, \"p999_ns\": %.1f, \"batch_ns_per_row\": %.1f, "
                "\"max_abs_diff\": %.3g, \"argmax_agreement\": %.6f}\n",
                pct(0.50), pct(0.99), pct(0.999), batch_ns, max_diff, static_cast<double>(agree) / n);
    return 0;
}
